#define DEVICE_PORT 0x1A0
unsigned char data_buffer[64];
unsigned short port_addr = DEVICE_PORT;
unsigned long count = 64;
int status;

// 1. Acquire I/O port permissions (root required)
// Requires a 1-byte span starting at port_addr, enabled (1)
status = ioperm(port_addr, 1, 1);

if (status == 0) {
    // 2. Perform Block Input (Input String Byte)
    // Read 'count' bytes from 'port_addr' into 'data_buffer'
    insb(port_addr, data_buffer, count);
}

